import os
import boto3
from agents import function_tool

_s3 = boto3.client("s3")


@function_tool
def upload_file_to_s3_bucket(local_path: str, bucket: str, key: str) -> str:
    if not os.path.isfile(local_path):
        return f"Not a file: {local_path}"
    try:
        with open(local_path, "rb") as fh:
            _s3.upload_fileobj(
                fh,
                bucket,
                key,
                ExtraArgs={"ServerSideEncryption": "AES256"},
            )
    except Exception as exc:
        return f"Upload failed: {exc}"
    return f"Uploaded {local_path} to s3://{bucket}/{key}"

import shutil
from dataclasses import dataclass, field
from pathlib import Path
from agents import function_tool


@dataclass
class MoveReport:
    moved: list = field(default_factory=list)
    skipped: list = field(default_factory=list)


@function_tool
def move_files_by_pattern(source_dir: str, dest_dir: str, pattern: str) -> MoveReport:
    report = MoveReport()
    src = Path(source_dir)
    dest = Path(dest_dir)
    if not src.is_dir() or not dest.is_dir():
        report.skipped.append("source or destination is not a directory")
        return report
    for item in src.glob(pattern):
        if not item.is_file():
            continue
        target = dest / item.name
        if target.exists():
            report.skipped.append(item.name)
            continue
        shutil.move(str(item), str(target))
        report.moved.append(item.name)
    return report
